#!/bin/sh
# The deterministic suite: the package's unit tests, then the wire
# vectors (tests/wire, generated by tests/wire/gen.py and checked there
# against pika), and the connection against scripted brokers (tests/fake).
set -eu

repo=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
slangc=${SLANGC:-slangc}
run_dir=$(mktemp -d "${TMPDIR:-/tmp}/amqp-test.XXXXXX")
trap 'rm -rf "$run_dir"' EXIT HUP INT TERM

(cd "$repo" && "$slangc" test src/amqp)
for t in wire fake; do
    actual=$(cd "$run_dir" && "$slangc" "$repo/tests/$t/main.sl" --run 2>/dev/null)
    expected=$(cat "$repo/tests/$t/expected.txt")
    if [ "$actual" != "$expected" ]; then
        printf '%s\n' "amqp tests ($t): output mismatch" >&2
        printf '%s\n' "$actual" > "$run_dir/actual.txt"
        diff "$repo/tests/$t/expected.txt" "$run_dir/actual.txt" | head -20 >&2 || true
        exit 1
    fi
    printf '%s\n' "PASS $t ($(printf '%s\n' "$expected" | wc -l | tr -d ' ') lines)"
done
